// === Tab: mySketch ===
// #RecodeRethink https://openprocessing.org/curation/72108
// "Mime" by Zaron Chen [ZRNOF]
// Recode: https://openprocessing.org/sketch/1617296

let canvasWidth = 600;
let canvasHeight = 600;
let stampAmount = 5;
let baseRadius = 500;
let contourWeight = 2;
let contourAmount = 100;
let contourDensity = 125;
let contourRough = 0.05;
let borderWeight = 5;

let dustShader;
let WebGL;
let Canvas;

let colors = [ "#FFFFFF", "#000000", "#AAAAAA", "#FF3333", "#00FFFF", "#FFFF00" ];
let mono = colors.slice(0, 3);
let ci;

function preload() {
	dustShader = createShader(vert, frag);
}

let clr;
function setup() {
	Canvas = createCanvas(canvasWidth, canvasHeight);
	noStroke();
	rectMode(CENTER);

	// init color information
	ci = new ColorInfo(colors);

	background("#233B5D");

	// background
	push();
	clr = random(mono);
	fill(clr);
	rectMode(CORNER);
	rect(0, 0, width, height);
	ci.update(clr, 1);
	pop();

	baseRadius = random() < 0.9 ? baseRadius : 1500;

	let dir = getStampDir();
	for (let a = 0; a < stampAmount; a++) {
		// stamp
		let pos = setStampPos(dir, a, stampAmount);
		baseRadius -= 80;
		contourAmount -= 10;
		shadow("#000000", 10, random(-100, 100), random(-100, 100));
		clr = random() < 0.95 ? random(mono) : "#AAAAAA";
		ci.update(clr, 1);
		stamp(pos.x, pos.y, clr, baseRadius);

		// rectangle
		shadow("#000000", 10, random(-100, 100), random(-100, 100));
		clr = random() < 0.95 ? random(mono) : "#FF3333";
		ci.update(clr, 1);
		fill(clr);
		rect(random(width), random(height), random(10, 80), height);

		// circle
		if (a == 0) continue;
		shadowBlur( random(0, 100) );
		clr = random() < 0.9 ? "#00FFFF" : "#FFFF00";
		ci.update(clr, 1);
		fill(clr);
		circle(pos.x, pos.y, 50);
	}

	// Shader (random dust filter)
	WebGL = createGraphics(width, height, WEBGL);
	WebGL.shader(dustShader);
	dustShader.setUniform('iCanvas', Canvas);
	WebGL.rect(0, 0, width, height);
	image(WebGL, 0, 0);

	// reset shadow
	noShadow();

	// Border, Color chart or bar ( bottom-right )
	let showColorFunc;
	if ( random() < 0.5 ) showColorFunc = colorChart;
	else showColorFunc = colorBar;
	for (let i = 0 ; i < 3; i++) {
		for (let blur = 150; blur >= 0; blur -= 50) {
			shadowBlur(blur);
			showColorFunc(10);
			Border("#FFFFFF", borderWeight);
		}
	}
}

// temp
function colorChart(unit) {
	rectMode(CORNER);
	let count = 1;
	for (let clr of colors) {
		let ts = ci.info[clr];
		if (ts == 0) continue;
		fill(clr);
		let x = width-(unit*ts+borderWeight);
		let y = height-(unit*count+borderWeight);
		rect(x, y, unit*ts, unit);
		count += 1;
	}
}

// temp
function colorBar(unit) {
	rectMode(CORNER);
	var count = 1;
	let sum = 0;
	for (let clr of colors) {
		var ts = ci.info[clr];
		sum += ts;
		fill(clr);
		var x = width-(unit+borderWeight);
		var y = height-(unit*sum+borderWeight);
		rect(x, y, unit, unit*ts);
		count += 1;
	}
}

function getStampDir() {
	const dirX = random( ['LTR', 'RTL', 'FIX'] );
	const dirY = random( ['TTB', 'BTT', 'FIX'] );
	return { x: dirX, y: dirY };
}

function setStampPos(dir, amount, stampAmount) {
	let posX, posY;
	if (dir.x == 'LTR') posX = map(amount, 0, stampAmount, 0, width);
	if (dir.x == 'RTL') posX = map(amount, 0, stampAmount, width, 0);
	if (dir.x == 'FIX') posX = width/2;
	if (dir.y == 'TTB') posY = map(amount, 0, stampAmount, 0, height);
	if (dir.y == 'BTT') posY = map(amount, 0, stampAmount, height, 0);
	if (dir.y == 'FIX') posY = height/2;
	return { x: posX, y: posY };
}

function stamp(posX, posY, clr, size) {
	push();
	translate(posX, posY);
	let st = random(0, 1000);
	let ed = st+contourAmount;
	for (let s = st; s < ed; s++) {
		stroke(clr);
		strokeWeight(random(contourWeight));
		noFill();
		let SCV = []; // smooth close vertex
		beginShape();
		for (let i = 0; i < TWO_PI; i += contourRough) {
			let noiseX = map(cos(i), -1, 1, 0, 1);
			let noiseY = map(sin(i), -1, 1, 0, 1);
			let n = noise(noiseX, noiseY, s/contourDensity);
			var x = cos(i) * size * n;
			var y = sin(i) * size * n;
			curveVertex(x, y);
			if (SCV.length < 3) SCV.push( [x, y] );
		}
		for (let scv of SCV) curveVertex(...scv);
		endShape();
		size -= 1;
	}
	pop();
}


// === Tab: ColorInfo ===
// not done

class ColorInfo {
	constructor(colors) {
		this.colors = colors;
		this.init();
	}
	init() {
		this.info = {};
		for (const clr of this.colors) {
			this.set(clr, 0);
		}
	}
	add(clr) {
		if (this.exist(clr)) return;
		this.colors.push(clr);
		this.set(clr, 0);
	}
	set(clr, num) {
		this.info[clr] = num;
	}
	update(clr, num) {
		this.info[clr] += num;
	}
	exist(clr) {
		return this.info.hasOwnProperty(clr);
	}
}

// === Tab: shadow ===
let shadowColor = (clr) => drawingContext.shadowColor = clr;

let shadowBlur = (blur) => drawingContext.shadowBlur = blur;

let shadowOffsetX = (xOff) => drawingContext.shadowOffsetX = xOff;
let shadowOffsetY = (yOff) => drawingContext.shadowOffsetY = yOff;
let shadowOffset = (xOff, yOff) => {
	drawingContext.shadowOffsetX = xOff;
	drawingContext.shadowOffsetY = yOff;
}

let shadow = (clr, blur, xOff, yOff) => {
	drawingContext.shadowColor = clr;
	drawingContext.shadowBlur = blur;
	drawingContext.shadowOffsetX = xOff;
	drawingContext.shadowOffsetY = yOff;
}

let noShadow = () => {
	drawingContext.shadowColor = "#000000";
	drawingContext.shadowBlur = 0;
	drawingContext.shadowOffsetX = 0;
	drawingContext.shadowOffsetY = 0;
}

// === Tab: tool ===
// Draw border for canvas
function Border(color, weight) {
  push();
  noFill();
  stroke(color);
  strokeWeight(weight*2);
  rectMode(CENTER);
  rect(width/2, height/2, width, height);
  pop();
}

// Show frame rate
function showFrameRate(posX=10, posY=35, SIZE=35, COLOR="#0088BB") {
  push();
  textSize(SIZE);
  fill(COLOR);
  text(floor(frameRate()), posX, posY);
  pop();
}

// Check click
let CLICK = false;
function mouseClicked() {
  CLICK = !CLICK;
  if (!CLICK) loop();
}

// Click to noloop
function ClickStop() { if (CLICK) noLoop(); }


// === Tab: frag ===
// noprotect

const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform sampler2D iCanvas;

	float random(vec2 uv) {
		return fract(tan(
			sin(tan(uv.y)*(uv.x+2718.))*2718.+
			cos(tan(uv.x)*(uv.y+3141.))*3141.
		)/1.);
	}

	float dust(vec2 uv, float oriChannel, float dustChannel, float wei) {
		oriChannel += dustChannel*wei;
		return oriChannel-wei/2.;
	}

	varying vec2 vTexCoord;
	void main() {
		vec2 uv = vTexCoord;
		uv.y = 1.-uv.y;
		vec4 canvas = texture2D(iCanvas, uv);
		vec4 color = vec4(
			dust(uv, canvas.r, random(uv), 0.5),
			dust(uv, canvas.g, random(uv), 0.5),
			dust(uv, canvas.b, random(uv), 0.5),
			1.
		);
		gl_FragColor = color;
	}
`

// === Tab: vert ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/how-to-write-a-shader

const vert = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`

